import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str) or not isinstance(temp_dir, str):
        raise TypeError("Invalid input type")
    if not os.path.exists(script_path) or not script_path.endswith('.py'):
        raise OSError("Invalid script path")
    if not os.path.exists(temp_dir):
        os.makedirs(temp_dir)
    temp_script_path = os.path.join(temp_dir, os.path.basename(script_path))
    shutil.copy(script_path, temp_script_path)
    try:
        result = subprocess.run(['python', temp_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str) or not isinstance(duration, int):
        raise TypeError("Invalid input types")
    if not os.path.exists(r_script_path):
        raise OSError("R script file does not exist")
    subprocess.Popen(['Rscript', r_script_path])
    start_time = time.time()
    while time.time() - start_time < duration:
        if glob.glob(output_path):
            return True, 'File generated successfully within the specified duration.'
        time.sleep(0.1)
    return False, 'File not generated within the specified duration.'

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    results = {}
    for ip in network.hosts():
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            results[str(ip)] = True
        except subprocess.CalledProcessError:
            results[str(ip)] = False
    return results

