import subprocess
import platform
import time
def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("Invalid URL")
    system = platform.system()
    if system == "Windows":
        command = ["start", url]
    elif system == "Darwin":
        command = ["open", url]
    elif system == "Linux":
        command = ["xdg-open", url]
    else:
        raise OSError("Unsupported operating system")
    process = subprocess.Popen(command, shell=True)
    time.sleep(1)
    return process.poll()

