def task_func(directory_path):
    if not isinstance(directory_path, str):
        raise TypeError("Invalid directory path type")
    if not os.path.exists(directory_path):
        raise OSError("Directory does not exist")
    results = []
    for file_path in glob.glob(os.path.join(directory_path, "*.bat")):
        try:
            process = subprocess.run([file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
            results.append((os.path.basename(file_path), process.returncode))
        except Exception:
            results.append((os.path.basename(file_path), None))
    return results

import subprocess
import time
import threading
def task_func(file_list):
    if not isinstance(file_list, list) or not all(isinstance(file, str) for file in file_list):
        raise TypeError("file_list must be a list of strings")
    exit_codes = []
    def run_file(file, results):
        try:
            process = subprocess.Popen(file, shell=True)
            process.wait()
            results.append(process.returncode)
        except Exception:
            results.append(-1)
    threads = []
    for file in file_list:
        thread = threading.Thread(target=run_file, args=(file, exit_codes))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    return exit_codes

