import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder) or not os.path.exists(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist.', 'failed_files': []}
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file in files:
        try:
            subprocess.run(['gzip', file], check=True)
            compressed_file = file + '.gz'
            shutil.move(compressed_file, dst_folder)
        except Exception:
            failed_files.append(os.path.basename(file))
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully.', 'failed_files': []}
    return {'success': False, 'message': 'Some files failed to compress or move.', 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str) or not os.path.exists(script_path):
        raise ValueError("Invalid script path")
    process = subprocess.Popen(['bash', script_path])
    pid = process.pid
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    try:
        while time.time() - start_time < timeout:
            if process.poll() is not None:
                break
            proc = psutil.Process(pid)
            cpu_usage += proc.cpu_percent(interval=0.1)
            memory_usage += proc.memory_info().rss
        else:
            process.terminate()
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

